"""Generate evidence-linked reports from completed audit tables."""
import pandas as pd
import numpy as np

def write_report(root):
    out=root/'outputs/metrics'; doc=root/'docs/dataset_audit'
    def read(n): return pd.read_csv(out/('idrid_'+n+'.csv'))
    def table(d):
        return '| '+' | '.join(map(str,d.columns))+' |\n| '+' | '.join(['---']*len(d.columns))+' |\n'+'\n'.join('| '+' | '.join(str(x).replace('|','/') for x in r)+' |' for r in d.itertuples(index=False,name=None))
    im=read('image_metadata');g=read('grading_labels');m=read('segmentation_metadata');cov=read('annotation_coverage');res=read('resolution_analysis');cross=read('cross_task_mapping');checks=read('integrity_checks');loc=read('localization_metadata');dist=read('grading_distribution');comp=read('component_areas');near=read('near_duplicate_candidates')
    gr=im[im.component=='Disease Grading'];sg=im[im.component=='Segmentation'];unique=im.drop_duplicates('decoded_sha256')
    agg=res.groupby(['mask_type','target_width']).agg(original_positive_pixels=('original_positive_pixels','sum'),resized_positive_pixels=('resized_positive_pixels','sum'),equivalent_pixels=('original_equivalent_pixels','sum'),original_components=('original_components','sum'),retained_components=('source_components_retained','sum'),disappeared_components=('source_components_disappeared','sum'),resized_components=('resized_components','sum'),merger_proxy=('merger_count_proxy','sum')).reset_index()
    agg['components_retained_percent']=(100*agg.retained_components/agg.original_components).round(3)
    agg['area_relative_to_expected_percent']=(100*agg.equivalent_pixels/agg.original_positive_pixels).round(3)
    agg.to_csv(out/'idrid_resolution_summary.csv',index=False)
    summary=m.groupby('mask_type').agg(masks=('path','size'),empty_masks=('empty','sum'),positive_pixels_min=('positive_pixels','min'),positive_pixels_median=('positive_pixels','median'),positive_pixels_mean=('positive_pixels','mean'),positive_pixels_max=('positive_pixels','max'),image_percent_median=('positive_image_percent','median')).round(5).reset_index()
    summary.to_csv(out/'idrid_lesion_area_summary.csv',index=False)
    areas=comp.groupby('mask_type').area_pixels.agg(['count','min','median','mean','max']).round(3).reset_index();areas.to_csv(out/'idrid_component_summary.csv',index=False)
    counts=im.groupby(['component','split']).size().reset_index(name='images')
    imbalance=pd.DataFrame([dict(split=s,n=len(z),majority_grades=str(sorted(z.DR_grade.value_counts()[lambda v:v==v.max()].index.tolist())),minority_grades=str(sorted(z.DR_grade.value_counts()[lambda v:v==v.min()].index.tolist())),max_min_ratio=float(z.DR_grade.value_counts().max()/z.DR_grade.value_counts().min()),majority_baseline_accuracy=float(z.DR_grade.value_counts().max()/len(z)),entropy_bits=float(-(z.DR_grade.value_counts(normalize=True)*np.log2(z.DR_grade.value_counts(normalize=True))).sum())) for s,z in [('all',g),*g.groupby('split')]])
    imbalance.to_csv(out/'idrid_imbalance_indicators.csv',index=False)
    rows=[
    ('DR grading','Moderate',f'{len(g)} labeled images, ordinal grades 0–4','Small imbalanced single source','Internal benchmark; test fine-tuning hypotheses'),
    ('Lesion segmentation','Strong',f'{len(sg)} expert-annotated photographs','Small selected diseased subset; incomplete type coverage','Pixel annotation research'),
    ('MA segmentation','Moderate',str(int((m.mask_type=='MA').sum()))+' masks','Tiny components vulnerable to resizing','Small-lesion internal benchmark'),
    ('HE segmentation','Moderate',str(int((m.mask_type=='HE').sum()))+' masks','Absent-mask semantics; limited diversity','Internal lesion research'),
    ('EX segmentation','Strong',str(int((m.mask_type=='EX').sum()))+' masks','One acquisition domain','Internal pixel annotation benchmark'),
    ('SE segmentation','Limited',str(int((m.mask_type=='SE').sum()))+' masks','Few examples and partial coverage','Exploratory segmentation'),
    ('Anatomical localization','Strong',str(len(loc))+' center records plus OD masks','Coordinate convention and domain limits','OD/fovea spatial research'),
    ('Image-quality modeling','Unsuitable / unsupported','Descriptive proxies only','No clinical gradability labels','Outlier review only'),
    ('Internal training','Moderate','Organizer train partition','Small effective sample; unknown patients','Preserve test; define validation within train'),
    ('Internal validation','Limited','Training can be subdivided','No official validation; patient grouping unavailable','Prespecify training-only validation'),
    ('Internal testing / evaluation','Moderate','Organizer test and labels','Small strata; test reuse bias','Locked internal test, per-class uncertainty'),
    ('External validation after IDRiD training','Unsuitable / unsupported','Same underlying collection','Internal test after IDRiD training','Obtain independent licensed dataset'),
    ('External validation of an independently trained model','Moderate','Distinct source only if training excludes IDRiD and related images','Narrow acquisition domain; overlap must be ruled out','Possible external benchmark, not broad deployment proof'),
    ('Domain-generalization evaluation','Unsuitable / unsupported','Single documented clinic/camera','No independent domain contrast','Evaluate separate institutions/cameras'),
    ('Multi-task learning','Moderate',str(int((cross.grading_available & cross.segmentation_available).sum()))+' content-matched grading/segmentation groups','Partial supervision; cross-task split leakage','Content-group protected exploration'),
    ('Explainability research','Moderate','Lesion and anatomy reference annotations','Localization overlap does not prove faithfulness','Reference localization and human study later')]
    suit=pd.DataFrame(rows,columns=['Task','IDRiD suitability','Evidence','Main limitation','Recommended role']);suit.to_csv(out/'idrid_suitability_matrix.csv',index=False)
    (doc/'IDRiD_SUITABILITY_MATRIX.md').write_text('# IDRiD suitability matrix\n\nTask-relative research judgments; Strong means useful reference annotations for an internal task, not deployment readiness or sufficient sample size.\n\n'+table(suit)+'\n',encoding='utf-8')
    limitations='''# Limitations, risks, unknowns and threats to validity

**Patient-level leakage cannot be fully audited from the publicly available identifiers.** No patient, paired-eye or visit key was found in local CSV schemas. Image serials do not establish independent patients.

- Small and imbalanced training/test strata constrain learning and evaluation precision. No official validation partition was found. Repeated test use for model selection biases final evaluation.
- Adequate-quality, disease-stratified selection cannot establish screening prevalence or performance on ungradable images. No gradability target exists locally.
- One documented clinic/camera domain cannot establish broad Indian, rural, multi-hospital, multi-camera, ethnic or protocol representation. Age, sex, ethnicity, residence, patient counts, diabetes duration and their distributions remain unknown from local annotations.
- Absent HE/SE masks are not explicit empty masks and must not silently become verified negative labels. Boundary uncertainty and inter-rater agreement are not quantified locally.
- Mask encodings differ: one EX mask is RGBA with fully opaque alpha. Treating alpha as foreground yields incorrect areas; downstream loaders must preserve the documented RGB-only semantic interpretation.
- DME labels reflect photographic hard-exudate proximity risk, not OCT-confirmed retinal thickening or clinical DME diagnosis.
- IDs reset across splits/tasks. Filename joins can misassign labels. Auxiliary-task training can leak a grading test image through shared content.
- Exact hashes exclude only byte/decoded-pixel duplicates. Perceptual screening cannot exclude arbitrary crops, transforms, fellow eyes or repeated visits; candidate pairs need review.
- Quality proxies use a fixed 512×340 view and include dark borders. Foreground thresholding is not a validated retinal mask; blur statistics are not clinical gradability labels.
- Nearest-neighbor component sampling is a geometric annotation experiment, not lesion visibility or model performance. Connected regions need not be distinct biological lesions. Component merging/fragmentation and lack of physical pixel calibration limit interpretation.
- CSV headers do not establish zero- versus one-based coordinate origin. Passing bounds under both conventions cannot resolve it; overlays use top-left plotting coordinates for inspection.
- No publisher checksum was supplied. Archive CRC and local hash comparisons establish internal consistency, not authoritative authenticity. Immutability covers paths, sizes, modification timestamps and bytes during this run, not historical provenance or access times.
- CC BY 4.0 requires attribution; licensing does not establish clinical effectiveness or regulatory approval.
- Internal results cannot establish external generalization, uncertainty calibration, referral benefit, explanation faithfulness, prospective workflow safety or autonomous diagnostic validity.
'''
    conflicts=read('content_label_conflicts') if (out/'idrid_content_label_conflicts.csv').exists() else pd.DataFrame()
    similarity=read('cross_task_similarity_candidates') if (out/'idrid_cross_task_similarity_candidates.csv').exists() else pd.DataFrame()
    if len(conflicts):
        limitations+='\n## Verified critical integrity failure\n\nExact decoded content carries conflicting disease grades across organizer train/test. Do not silently deduplicate, relabel or treat the official test as independent. Resolve provenance and predefine handling before training. Raw files were preserved.\n\n'+table(conflicts)+'\n'
        suit.loc[suit.Task=='DR grading','IDRiD suitability']='Limited until integrity issue resolved'
        suit.loc[suit.Task=='DR grading','Main limitation']='Exact train/test duplicate has conflicting grades, plus small imbalanced single source'
        suit.to_csv(out/'idrid_suitability_matrix.csv',index=False)
        (doc/'IDRiD_SUITABILITY_MATRIX.md').write_text('# IDRiD suitability matrix\n\nTask-relative internal research ratings. Resolve exact duplicate/label conflict before model decisions.\n\n'+table(suit)+'\n',encoding='utf-8')
    (doc/'IDRiD_LIMITATIONS.md').write_text(limitations,encoding='utf-8')
    sections=[]
    def add(title,text):sections.append('## '+title+'\n\n'+text+'\n')
    add('Scope, evidence categories and execution','Audit date: 2026-10-28 (Asia/Calcutta); fixed seed 20261028. No training or final model/preprocessing/resolution/loss/referral decision. **Patient-level leakage cannot be fully audited from the publicly available identifiers.**\n\n**Verified local observations** are computed in the CSV tables. **Documentation facts** are attributed to sources below. **Interpretations** explain consequences, not clinical diagnoses. **Unknowns** remain explicit. **Future implications** are hypotheses and evaluation requirements, not selected methods.')
    if len(conflicts):add('Critical verified finding: split overlap with inconsistent labels',table(conflicts)+'\n\nThe bytes and decoded pixels establish identical image content, yet these CSV grades disagree. This is a local dataset integrity failure, not an inferred clinical diagnosis. Archive/extraction comparisons indicate whether the retained packages also contain the issue. The organizer documentation claim of no duplicates conflicts with this observed local result. Do not alter raw files or silently repair labels. Resolve author/source provenance and prespecify any exclusion/label policy before training. Review exact_duplicate_label_conflict.png. The cross-task mapping retains all conflicting label records and leaves its single-valued DR/DME fields unset for ambiguous groups.')
    if len(similarity):add('Qualified cross-task image correspondence',table(similarity.groupby(['match_status','candidate_cross_split']).size().reset_index(name='segmentation_images'))+'\n\nExact decoded matching alone cannot recognize recompression. Every segmentation image was compared to every grading image using 64×64 bilinear RGB mean absolute error, Pearson correlation and second-best separation. High-similarity candidates require MAE≤2/255, correlation≥0.995 and a ≥5 intensity-unit margin to the second best. Full-resolution MAE/max/equal-pixel fractions are measured for nonexact high-similarity pairs. These criteria are heuristic evidence of shared imagery, not proof of patient or byte identity. Candidate grading labels remain explicitly qualified in separate candidate fields. Review idrid_cross_task_similarity_candidates.csv and cross_task_candidate_pairs.png; exact and approximate results are never silently conflated.')
    if (out/'idrid_csv_row_classification.csv').exists():add('CSV export artifacts distinguished from annotations',table(read('csv_row_classification'))+'\n\nAll-blank core rows are export padding, not missing patient annotations. Exact raw schema/missing/duplicate counts remain in idrid_csv_schema.csv; the localization metadata contains usable nonblank rows. One training grading extra-field cell at IDRiD_405 contains only whitespace; it is semantically empty and not an extra target. No raw CSV was rewritten. Initial localization bounds/duplicate failures caused by parsing padding as annotations were corrected by explicitly classifying those rows; this was a parser issue, not a dataset coordinate failure.')
    if (out/'idrid_ma_component_topology_summary.csv').exists():add('MA collapse and merger tracing',table(read('ma_component_topology_summary'))+'\n\nCollapsed-to-one-pixel counts are surviving source components represented by exactly one target pixel. Merged-region counts explicitly trace multiple source IDs into each eight-connected target region; fragmentation is counted separately. These supplement the net merger proxy in the all-lesion resolution table.')
    if (out/'idrid_repeated_content_localization_variation.csv').exists():add('Repeated-image center annotation variation',table(read('repeated_content_localization_variation'))+'\n\nThe same decoded photographs can have slightly different center annotations across duplicate IDs. These are measured pixel disagreements, not proof of a wrong clinical location. They demonstrate reference variability even for identical imagery; pixel offsets are not physical distances.')
    if (out/'idrid_mask_encoding_audit.csv').exists():add('Mask encoding and alpha-channel handling',table(read('mask_encoding_audit').groupby(['mode','channels','foreground_rule']).size().reset_index(name='masks'))+'\n\n362 masks use indexed palettes with scalar values 0/1. IDRiD_81_EX.tif is RGBA: red is 0/255, green/blue are zero, and alpha is 255 everywhere. The actual foreground is 312,918 pixels (2.5623% of the canvas), not the opaque alpha channel. Foreground decoding excludes alpha. A final sanity check caught and corrected an initial any-channel interpretation that would have falsely labeled the entire canvas foreground. Component areas, coverage statistics, resolution tables and EX figures were regenerated from RGB foreground. Exact palette/alpha evidence is in idrid_mask_encoding_audit.csv; raw bytes were unchanged.')
    add('1. Inventory and extraction integrity','Actual raw root: data/raw/IDRiD, with archives and nested original/A/B/C packages. Archives are not additional samples. idrid_directory_tree.txt records every directory; inventory records every path, extension, byte count and SHA-256. Filename collisions are enumerated separately.\n\n'+table(read('inventory_summary'))+'\n\nZip CRC was checked. Local archive consistency cannot establish publisher authenticity without external checksums. No remote per-file manifest was supplied; documented totals and bidirectional correspondence provide completeness evidence. Unexpected, zero-byte and unreadable outcomes appear in integrity checks.')
    add('2. Fundus image integrity',table(counts)+'\n\n'+table(im.groupby(['width','height','mode','channels','format']).size().reset_index(name='files'))+f'\n\n{len(im)} file instances correspond to {len(unique)} unique decoded-content groups. Every image was fully decoded. Metadata includes aspect ratio, mode/channels, dtype, format, file size, pixel range/mean/std, RGB moments, byte hashes and mode/size-aware decoded hashes. These tables expose grayscale, unusual dimensions and corrupt files. Cross-task duplicates are separated from cross-split leakage.')
    add('3–5. Disease labels, distributions and ordinal implications','idrid_csv_schema.csv preserves exact headers including whitespace, inferred types, missing counts, duplicate rows/IDs and blank trailing export columns. The first three content columns are parsed without rewriting raw CSVs. Orphan image/label matches are checked in both directions separately by split.\n\n'+table(dist)+'\n\n'+table(imbalance.round(5))+'\n\n**Interpretation:** rare classes constrain learning and precision. Majority-baseline accuracy is label arithmetic, not model performance; aggregate accuracy can hide minority failure. Selected disease distributions are not population prevalence.\n\n**Ordinal target:** observed values are checked against 0→1→2→3→4, increasing severity. Standard ICDR terms are no apparent DR, mild NPDR, moderate NPDR, severe NPDR and proliferative DR; the descriptor loosely calls grade 4 severe, so future implementation should adopt the actual grading standard explicitly. A 4→3 error is one step; 4→0 is four steps and grossly understates severity. Step distance is not calibrated clinical utility.\n\n**Future implications:** evaluate confusion matrix, per-class sensitivity/recall, macro F1, balanced accuracy and quadratic weighted kappa with uncertainty. Kappa depends on marginals and ordinal distance. Define any referral threshold from an adopted standard later; none invented here. Sampling, weighting and ordinal formulations are possible hypotheses, not chosen approaches.')
    add('6. DME labels audited separately',table(read('dme_distribution'))+'\n\n'+table(read('dr_dme_crosstab'))+'\n\n**Documentation:** labels represent hard-exudate occurrence/proximity to the macular center using Messidor-derived risk definitions. They are not OCT-confirmed thickening. Cross-tabs describe association, not causality or interchangeability with DR. Missing/invalid DME values are checked independently.')
    add('7–8. Segmentation, coverage and sparsity',table(cov.round(5))+'\n\n'+table(summary)+'\n\n'+table(areas)+'\n\nPer-mask metadata records exact dtype, dimensions, unique values, binary status, empty status and counts. Correspondence is split-aware within segmentation; missing image/type combinations are explicit in idrid_missing_masks.csv. Missing masks are not assumed negative. Coverage is not population lesion prevalence. OD is anatomy, not a lesion class.\n\nArea percentages use the **full image canvas**, not a validated retinal-area denominator. Eight-connected components are geometric annotation regions, not independent clinical lesion counts. Pixel accuracy can be misleading under sparse foreground. Dice/Focal/Tversky remain future hypotheses; no loss is selected.')
    add('9. Resolution and small-lesion risk','All operations were in memory; target sizes mean **width**, preserving aspect ratio with rounded height. No square warp/crop is implied. Original eight-connected component IDs are nearest-neighbor sampled, simultaneously preserving binary sampling semantics and identifying which source components survive. Retained source IDs count original regions sampled at least once; disappearance is exact for this interpolation. Target regions may merge or fragment; merger_proxy=max(0,retained IDs−target components) is only a net topology proxy.\n\n'+table(agg.round(3))+'\n\nRaw positive pixels across grids are not directly comparable; area_relative_to_expected_percent corrects for geometric scale. Small components can disappear despite stable total normalized area. This establishes annotation sampling risk, not human/model visibility or diagnostic performance. Tiles, multiscale inputs or larger views remain hypotheses; no final resolution is selected.')
    add('10–11. Visual audit and image characteristics','Deterministic grade grids show up to six images per grade with split/ID, DR and DME. Four segmentation rows span both splits with original/MA/HE/EX/SE views: MA magenta, HE cyan, EX yellow, SE green. OD/fovea overlays, distributions and resolution plots are under outputs/figures/idrid_audit. Tiny lesions may disappear in reduced figures; raw-resolution review remains necessary. Figures enable manual inspection; no independent medical diagnoses or completed ophthalmologist review are claimed.\n\nFull-resolution pixel/RGB moments are in metadata. Brightness/contrast/black fraction/Laplacian variance use fixed 512×340 bilinear RGB proxy views. Gray is arithmetic RGB mean; black means maximum channel ≤15; foreground bbox is in proxy coordinates. This is not a validated retinal FOV mask. Laplacian uses scipy default reflect boundary handling. The fixed view has a slight aspect approximation solely for descriptive proxies. IQR fences Q1−1.5IQR/Q3+1.5IQR flag outliers for review, not clinical gradability. Pigmentation/pathology/content as well as exposure and blur can change these statistics.')
    add('12. Localization',table(loc.groupby(['split','anatomy']).agg(rows=('image_id','size'),in_bounds=('within_zero_based_bounds','sum')).reset_index())+'\n\nLocal CSVs provide OD/fovea X/Y centers. OD region masks belong to segmentation, not the localization package. Bounds and bidirectional coverage are checked. Both candidate coordinate-origin bounds are recorded; bounds alone cannot establish indexing. Plotted overlays assume x horizontal, y vertical, top-left origin for inspection. Anatomy could support macular proximity descriptions and spatial reasoning; physical distance needs calibration, and grading improvement is not guaranteed.')
    add('13–14. Cross-task identity and leakage',table(cross.groupby(['grading_available','segmentation_available','localization_image_available']).size().reset_index(name='unique_content_groups'))+f'\n\nThe mapping joins by decoded content, then retrieves grading labels by matched grading split/ID. It retains all task/split/ID records and lesion/anatomy availability. Identical names are insufficient. Intentional cross-task shared supervision is not automatic leakage, but test image reuse through another task would leak information. Exact cross-split decoded groups: {int(cross.cross_split_content.sum())}.\n\nNear-duplicate candidates: {len(near)}. The final exhaustive grading-image screen uses 64×64 grayscale correlation ≥0.995 and RGB mean absolute error ≤5/255; false positives/negatives are possible. This replaces an intentionally loose initial mean-threshold hash screen. This cannot exclude arbitrary preprocessing-derived or patient-related duplicates. No patient/eye/visit linkage was found. **Patient-level leakage cannot be fully audited from the publicly available identifiers.**')
    add('15–16. Provenance and representativeness','**Verified local:** image dimensions/formats above, local LICENSE.txt/CC-BY-4.0.txt, organizer-named partitions and annotation schemas. No row-level demographics found.\n\n**Documentation:** [official data page](https://idrid.grand-challenge.org/Data/) describes a Nanded clinic, Kowa VX-10 alpha, 50-degree macula-centered images and lesion mask totals. [Primary 2018 descriptor](https://www.mdpi.com/2306-5729/3/3/25) reports 2009–2017 examinations at Eye Clinic, Sushrusha Hospital Building; mydriasis with 0.5% tropicamide. Trained student pixel markings underwent two retinal specialists’ consensus review; student center locations were averaged and retinal-expert checked; experts supplied grades. [Organizer page](https://idrid.grand-challenge.org/) records the 2018 challenge context. These are source-reported facts, not independently verified acquisition history here.\n\n**Unknown:** patient counts/linkage, age, sex, ethnicity, residence/rural status, diabetes duration, comorbidities and distributions; quantified annotator agreement and uncertainty.\n\n**Interpretation:** selected single-clinic/camera, mydriatic adequate-quality images cannot establish representation of India broadly, rural screening, multiple hospitals/cameras/protocols or ungradable real-world photographs. Do not infer demographics from location.')
    add('17–19. Splits, external validation and suitability','Official/local counts are above. No official validation split was found and no test images were merged into training. Prespecify training-only validation and cross-task identity protection. Small correlated samples constrain effective size; scratch-training sufficiency cannot be established by file counts. Fine-tuning is a plausible hypothesis to test, not an architecture choice. Multi-task gains need controlled evaluation.\n\nIDRiD test remains internal if IDRiD is used for training/fine-tuning. Require an independent licensed source, institutions/cameras/protocols/populations relevant to intended use, compatible adjudicated labels, adequate per-class size, patient/visit groups and documented absence of overlap. No external dataset was downloaded. Calibration, abstention, referral benefit and prospective clinical utility need separate evidence.\n\n'+table(suit))
    add('Integrity checks and failed/uncertain findings',table(checks)+'\n\nPASS applies only to the named definition. UNKNOWN/REVIEW are unresolved results. Raw before/after manifests compare path set, bytes, size and mtime_ns. Access times are not covered. All CSVs are reopened and plot presence checked. Original JPEG/TIFF files were not copied into generated code/output folders; figures are derived annotated thumbnails. Git evidence is unknown when the folder is not a repository.')
    answers=[
    ('What exactly does one sample represent?','A deidentified fundus photograph plus available annotations; not a verified independent patient or visit.'),
    ('How many grading images exist?',str(len(gr))),
    ('Official/local train and test counts?',counts.to_string(index=False)),
    ('Actual DR distributions?','Exact counts and percentages by split/all are in section 3–5 and idrid_grading_distribution.csv.'),
    ('How imbalanced?',imbalance.to_string(index=False)),
    ('What DME information exists?','Risk labels and DR cross-tabs; photographic exudate-proximity risk, not OCT thickening.'),
    ('How many pixel-annotated images?',str(len(sg))+' segmentation images; type coverage differs.'),
    ('Which lesions?','MA, HE, EX, SE; OD is separate anatomy.'),
    ('Masks for every lesion/image?','No; explicit absent combinations in idrid_missing_masks.csv. Absence is not a verified negative.'),
    ('How sparse?',summary.to_string(index=False)),
    ('How tiny are MAs?',areas[areas.mask_type=='MA'].to_string(index=False)+'; geometric pixel areas, not physical lesion sizes.'),
    ('Does aggressive resizing destroy MA information?',agg[agg.mask_type=='MA'][['target_width','retained_components','disappeared_components','components_retained_percent']].to_string(index=False)+'; sampling evidence, not model performance.'),
    ('What anatomy annotations?',str(len(loc))+' center rows plus '+str(int((m.mask_type=='OD').sum()))+' OD masks.'),
    ('Which task images overlap?',str(int((cross.grading_available & cross.segmentation_available).sum()))+' grading/segmentation content groups; all exact identities/splits in idrid_cross_task_mapping.csv.'),
    ('Can overlap support multi-task learning?','Potentially, using partial supervision and content-group split guards. Benefit is unproven.'),
    ('Are images duplicated?',str(len(im))+' file instances / '+str(len(unique))+' unique decoded groups; cross-task repeats are expected.'),
    ('Is there train/test leakage?',str(int(cross.cross_split_content.sum()))+' exact cross-split decoded groups. Other leakage is not ruled out.'),
    ('Can patient leakage be ruled out?','No. Patient-level leakage cannot be fully audited from the publicly available identifiers.'),
    ('What camera/domain?','Documented Nanded eye clinic, Kowa VX-10 alpha, 50-degree, mydriatic macula-centered photography.'),
    ('What demographics are available?','Clinic/population context reported by authors; no local row-level demographic columns.'),
    ('What demographics are missing?','Patient count, age/sex/ethnicity, residence, disease duration and distributions, eye/visit linkage.'),
    ('Representative of rural India?','Not established; no rural screening sampling frame or domain evidence.'),
    ('Enough for scratch deep training?','Not established. Small, imbalanced and potentially correlated samples limit claims; require learning curves and locked evaluation.'),
    ('Is fine-tuning more defensible?','A plausible future hypothesis with limited labels; benefit and pretraining overlap need evaluation.'),
    ('Can IDRiD alone validate generalization?','It cannot establish external generalization after IDRiD training.'),
    ('Exact project role?','Internal expert-annotated grading/lesion/anatomy research benchmark with protected test.'),
    ('Additional data needed?','Independent source/camera/population, compatible labels, adequate rare classes, patient linkage, quality targets, license and overlap audit.'),
    ('Disclosures to judges?','Small selected single domain; no patient-leakage exclusion; absent-mask ambiguity; photographic DME proxy; tiny-lesion resizing risk; no external/prospective validation. Research decision support only.')]
    add('20. All 28 required questions','\n\n'.join(f'### {i}. {q}\n\n{a}' for i,(q,a) in enumerate(answers,1)))
    add('Questions to resolve before model selection','1. What intended-use population, capture workflow, grading standard and human-review/referral policy will be adopted?\n2. Can authors clarify patient/eye/visit linkage, absent-mask semantics and coordinate origin?\n3. What independent dataset supplies compatible labels, relevant quality/camera variation and rare-grade sample size?\n4. How will training-only validation and cross-task content protection be prespecified and final test locked?\n5. What resolution/tiles/multiscale hypotheses preserve tiny MA signals, separately from predictive performance?\n6. How will ordinal errors, class imbalance, missing supervision and DME proxy meaning be evaluated before choosing losses?\n7. How will calibration, abstention, quality and explanation fidelity be validated with suitable targets and human reviewers?\n8. What learning curves and confidence intervals would justify capacity, fine-tuning or multi-task complexity?')
    add('Reproduce and review','From D:\\DR_Hackathon run `.venv\\Scripts\\python.exe src\\data\\audit_idrid.py`. Install with `.venv\\Scripts\\python.exe -m pip install -r requirements-audit.txt`. The driver discovers actual files and regenerates reports/tables/figures; no notebook edits needed. Versions/platform/seed are recorded in idrid_environment.json.\n\nReview IDRiD_LIMITATIONS.md, IDRiD_SUITABILITY_MATRIX.md, idrid_integrity_checks.csv, idrid_resolution_summary.csv, idrid_cross_task_mapping.csv, idrid_missing_masks.csv, idrid_quality_outliers.csv and the figures. Exact paths/headers are in inventory/schema CSVs.')
    (doc/'IDRiD_DATASET_AUDIT.md').write_text('# IDRiD research-grade dataset audit\n\n'+'\n'.join(sections),encoding='utf-8')
